{
    static SPI_HandleTypeDef h;
    ut_reset_regs();
    h.Instance = SPI1;
    h.State = HAL_SPI_STATE_RESET;
    /* h.Init.<field> = <a constant of stm32n6xx_hal_spi.h>; - one line per Init field the case needs */
    /* forge_host_spi.<REG> = <the flags a wait polls>; - preset: host registers are RAM */
